module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic x,
    output logic z
);

    logic [2:0] state, next_state;

    // State register
    always_ff @(posedge clk) begin
        if (reset) begin
            state <= 3'b000;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always_comb begin
        case (state)
            3'b000: next_state = x ? 3'b001 : 3'b000;
            3'b001: next_state = x ? 3'b100 : 3'b001;
            3'b010: next_state = x ? 3'b001 : 3'b010;
            3'b011: next_state = x ? 3'b010 : 3'b001;
            3'b100: next_state = x ? 3'b100 : 3'b011;
            default: next_state = 3'b000;
        endcase
    end

    // Output logic (Moore or Mealy? Output depends only on present state y[2:0] in table)
    // Let's check table output z:
    // 000: 0
    // 001: 0
    // 010: 0
    // 011: 1
    // 100: 1
    always_comb begin
        case (state)
            3'b000, 3'b001, 3'b010: z = 1'b0;
            3'b011, 3'b100:         z = 1'b1;
            default:                z = 1'b0;
        endcase
    end

endmodule

